

import React, { useRef, useEffect } from 'react';

const HtmlDialog = ({ onSubmit }) => {
  const textRef = useRef(null);

  useEffect(() => {
    // Mettre le focus sur le champ de texte lorsque le composant est monté
    if (textRef.current) {
      textRef.current.focus();
    }
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const text = textRef.current.value;
    onSubmit(text);
  };

  return (
    <form onSubmit={handleSubmit}>
      <br />
      <div>
        <h2>
          <label>Saisis ta première version ici</label>
        </h2>
      </div>
      <textarea
        ref={textRef}
        rows="10"
        cols="90"
        defaultValue={"Agis en tant que:\n\nOBJECTIF(S):\n\nCONTEXTE:\n"}
      />
      <br /><br />
      <button
        type="submit"
        style={{
          padding: '10px 20px',
          fontSize: '16px',
          backgroundColor: '#4CAF50',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          cursor: 'pointer'
        }}
      >
        1. Sélectionne les actions que tu veux
      </button>
    </form>
  );
};

export default HtmlDialog;
