

import React, { useState, useEffect } from 'react';
import { HashRouter as Router } from 'react-router-dom';
import HtmlDialog from './HtmlDialog';
import './App.css';

const VariantDialog = ({ onSubmit }) => {
  const [variantText, setVariantText] = useState('');

  const handleSubmit = () => {
    onSubmit(variantText);
  };

  return (
    <div className="dialog" style={{ display: 'flex', alignItems: 'center' }}>
      <h3 style={{ marginRight: '10px' }}>Combien veux-tu de variantes :</h3>
      <input
        type="number"
        value={variantText}
        onChange={(e) => setVariantText(e.target.value)}
        style={{ marginRight: '10px', width: '50px' }}
      />
      <button onClick={handleSubmit}>OK</button>
    </div>
  );
};

const AlertModal = ({ message, onClose }) => (
  <div className="modal-overlay">
    <div className="modal">
      <div>
        {message.split('\n').map((line, index) => (
          <React.Fragment key={index}>
            {line}
            <br />
          </React.Fragment>
        ))}
      </div>
      <button onClick={onClose}>OK</button>
    </div>
  </div>
);

function App() {
  const [submittedText, setSubmittedText] = useState('');
  const [selectedActions, setSelectedActions] = useState([]);
  const [executedActions, setExecutedActions] = useState([]);
  const [showActions, setShowActions] = useState(false);
  const [displayResult, setDisplayResult] = useState(false);
  const [variantDialogVisible, setVariantDialogVisible] = useState(false);
  const [actionResults, setActionResults] = useState({});
  const [variantCount, setVariantCount] = useState('');
  const [alertMessage, setAlertMessage] = useState('');
  const [actionsData, setActionsData] = useState([]);
  const [highlightCopyButton, setHighlightCopyButton] = useState(false);

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const version = urlParams.get('version') || '1';

    import(`./actionsData${version}.js`).then(module => {
      setActionsData(module.default);
    }).catch(err => {
      console.error('Failed to load actions data:', err);
    });
  }, []);

  const handleSubmit = (text) => {
    setSubmittedText(text);
    setShowActions(true);
    setDisplayResult(false);
    console.log('Texte soumis :', text);
  };

  const handleCheckboxChange = (e) => {
    const actionNo = parseInt(e.target.value);
    if (e.target.checked) {
      setSelectedActions([...selectedActions, actionNo]);
    } else {
      setSelectedActions(selectedActions.filter(no => no !== actionNo));
    }
  };

  const handleActionsSubmit = (e) => {
    e.preventDefault();
    setShowActions(false);
    setDisplayResult(true);
    setHighlightCopyButton(true);
    console.log('Actions demandées :', selectedActions);

    const newExecutedActions = [...executedActions];

    selectedActions.forEach(actionNo => {
      const action = actionsData.find(a => a.no === actionNo);
      if (action && action.fonction && functionsMap[action.fonction]) {
        functionsMap[action.fonction](submittedText);
      }
      newExecutedActions.push(actionNo);
    });

    setExecutedActions(newExecutedActions);
    setSelectedActions([]);
  };

  const proposeVariants = (text) => {
    setVariantDialogVisible(true);
  };

  const handleVariantSubmit = (count) => {
    setActionResults(prevResults => ({
      ...prevResults,
      proposeVariants: count,
    }));
    setVariantCount(count);
    setVariantDialogVisible(false);
  };

  const copyToClipboard = () => {
    let actionsChosen = executedActions.map((actionNo, index) => {
      const action = actionsData.find(action => action.no === actionNo);
      let actionResult = '';

      if (action.fonction === 'proposeVariants' && variantCount) {
        actionResult = `${variantCount} `;
      } else if (action.fonction && actionResults[action.fonction]) {
        actionResult = actionResults[action.fonction];
      }

      return `${index + 1}. ${action.action.replace('{n}', actionResult)}`;
    }).join('\n');

    const textToCopy = `Idée soumise :\n${submittedText}\n\nActions choisies :\n${actionsChosen}\n\n--------------------------------------------------------------------------------------------------\nAs-tu bien compris ?\nY aurait-il quelque chose d’important que j’aurais oublié ?\nDe quelles informations aurais-tu encore besoin pour mieux répondre à ma requête ?\nPrends ton temps pour répondre, c’est la qualité de ta réponse qui prime.`;
    navigator.clipboard.writeText(textToCopy).then(() => {
      setAlertMessage('BRAVO \nTa demande est maintenant dans ton presse-papier.  \n\nTu peux la soumettre à ton IA préférée.  \nMais n`oublie pas de vérifier la réponse avec une ou plusieurs autres IA, sinon gare aux hallucinations !\n\n2 avis valent mieux qu´un !\n\nAu besoin, complète ta demande, notamment en précisant le contexte, car le contexte permet à l´IA de fournir des réponses plus pertinentes et mieux adaptées à tes besoins spécifiques.\n\nBravo pour ta détermination !\nN\'oublie pas de relire attentivement la réponse de l\'IA.\nAssure-toi de bien comprendre chaque étape des actions proposées.\nSi quelque chose n\'est pas clair, n\'hésite pas à poser des questions.\nTon succès dépend de la précision et de la clarté de ta demande.');
    });
  };

  const functionsMap = {
    proposeVariants,
  };

  return (
    <Router>
      <div className="App three-column-margin">
        <HtmlDialog onSubmit={handleSubmit} />
        {submittedText && (
          <div>
            <button
              type="button"
              onClick={copyToClipboard}
              className={highlightCopyButton ? 'highlight' : ''}
              style={{ padding: '10px 20px', fontSize: '16px', margin: '10px 0' }}
            >
              3. Copie les actions à effectuer dans ton presse-papier
            </button>
            <h2>Idée soumise :</h2>
            <pre>{submittedText}</pre>
          </div>
        )}
        {showActions && (
          <div>
            <h2>Actions disponibles :</h2>
            <form onSubmit={handleActionsSubmit}>
              {actionsData.map(action => {
                const isActionExecuted = executedActions.includes(action.no);
                const isFunctionExecuted = action.fonction && executedActions.some(no => actionsData.find(a => a.no === no && a.fonction === action.fonction));
                return (
                  <div key={action.no}>
                    <label>
                      <input
                        type="checkbox"
                        value={action.no}
                        onChange={handleCheckboxChange}
                        disabled={isActionExecuted || isFunctionExecuted}
                      />
                      {action.action.replace('{n}', actionResults[action.fonction] || '')}
                    </label>
                  </div>
                );
              })}
              <hr />
              <div style={{ display: 'flex', justifyContent: 'flex-start', gap: '10px', margin: '10px 0' }}>
                <button type="submit" style={{
                  padding: '10px 20px',
                  fontSize: '16px',
                  backgroundColor: '#4CAF50',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: 'pointer'
                }}>
                  2. Soumets les actions à effectuer
                </button>
                <div style={{ width: '30%', backgroundColor: '#f2f2f2', padding: '10px', fontStyle: 'italic' }}>
                  Après avoir pressé sur le bouton 2,  <br />tu peux encore ajouter autant d'actions que tu le souhaites,  <br />il te suffit de presser sur le bouton 1
                </div>
              </div>
            </form>
          </div>
        )}
        {displayResult && (
          <div>
            <h2>Actions à effectuer :</h2>
            <ol>
              {executedActions.map((actionNo, index) => (
                <li key={actionNo}>
                  {actionsData.find(action => action.no === actionNo).action}
                  {actionsData.find(action => action.no === actionNo).fonction && (
                    <span>: {actionResults[actionsData.find(action => action.no === actionNo).fonction]}</span>
                  )}
                </li>
              ))}
            </ol>
          </div>
        )}
        {variantDialogVisible && (
          <VariantDialog
            onSubmit={handleVariantSubmit}
          />
        )}
        {alertMessage && (
          <AlertModal
            message={alertMessage}
            onClose={() => {
              setAlertMessage('');
              window.location.href = 'https://sites.google.com/view/satia-prompt/les-ia';
            }}
          />
        )}
      </div>
    </Router>
  );
}

export default App;
